"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[85841],{28453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>r});var s=n(96540);const o={},a=s.createContext(o);function i(e){const t=s.useContext(a);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),s.createElement(a.Provider,{value:t},e.children)}},88856:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>d,frontMatter:()=>i,metadata:()=>s,toc:()=>l});const s=JSON.parse('{"id":"tangfen/aboutdslreply","title":"","description":"Some people haven\'t understood Marx themselves yet oppose Marx -- that\'s nothing unusual; there are too many such people. Of course there are also some who shout about Marx every day yet fundamentally haven\'t understood Marx either. These two kinds of people basically constitute most of the arguments about Marx. But none of that is important. However, some basic principles should still be observed. For example, you should at minimum not distort someone\'s meaning, and at minimum not make obvious reading errors. For instance, in my post \\"Explaining a Kindergarten-Level Question About Marx to the Likes of [Dushulang]!\\" I had this passage:","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/aboutdslreply.md","sourceDirName":"tangfen","slug":"/tangfen/aboutdslreply","permalink":"/tangfen/aboutdslreply","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"aboutdslreply","title":"","hide_table_of_contents":true},"sidebar":"tangfenSidebar","previous":{"title":"[\u8bfb\u4e66\u72fc]\u3001\u533a\u533a\u5148\u751f\u3001\u6cd5\u5170\u897f\u5927\u83dc\u5e08\u5085\u7b49\u7b49\uff0c\u8bf7\u4e0d\u8981\u7ee7\u7eed\u52b3\u52a8\u91cf\u7eb2\u7684\u4f2a\u6982\u5ff5\uff01","permalink":"/tangfen/falseconcept"},"next":{"title":"\u5411[\u8bfb\u4e66\u72fc]\u4e4b\u6d41\u89e3\u91ca\u4e00\u4e2a\u5173\u4e8e\u9a6c\u514b\u601d\u7684\u5e7c\u513f\u56ed\u7ea7\u522b\u95ee\u9898\uff01","permalink":"/tangfen/abasicquestion"}}');var o=n(74848),a=n(28453);const i={id:"aboutdslreply",title:"",hide_table_of_contents:!0},r="Starting from [Dushulang]'s Reply: Please Read Carefully, Everyone, and Don't Get the Meaning Completely Backwards",h={},l=[];function u(e){const t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"starting-from-dushulangs-reply-please-read-carefully-everyone-and-dont-get-the-meaning-completely-backwards",children:"Starting from [Dushulang]'s Reply: Please Read Carefully, Everyone, and Don't Get the Meaning Completely Backwards"})}),"\n",(0,o.jsxs)(t.p,{children:["Some people haven't understood Marx themselves yet oppose Marx -- that's nothing unusual; there are too many such people. Of course there are also some who shout about Marx every day yet fundamentally haven't understood Marx either. These two kinds of people basically constitute most of the arguments about Marx. But none of that is important. However, some basic principles should still be observed. For example, you should at minimum not distort someone's meaning, and at minimum not make obvious reading errors. For instance, in my post \"Explaining a Kindergarten-Level Question About Marx to the Likes of [Dushulang]!\" I had this passage: ",(0,o.jsx)("br",{}),"\n\"Some people who can't even grasp the concept of dimensions might ask: what is the dimension of labor? Such people fundamentally don't know what dimension means. It's like asking: 'What is the dimension of the sun?' -- anyone who asks this basically has never studied physics. Dimension relates to measurement. For example, regarding the sun, if we examine it from the perspective of time, the dimension of the sun's lifespan is the dimension of time; if from the perspective of size, the dimension of the sun's volume is the cube of the length dimension. From this we know that asking 'what is the dimension of the sun?' only shows that the person doesn't understand dimensions at all! Similarly, asking 'what is the dimension of labor?' is the same. But from the perspective of value measurement, the dimension of the value of the labor-power commodity is likewise the currency dimension.\""]}),"\n",(0,o.jsxs)(t.p,{children:["That [Dushulang] actually replied: ",(0,o.jsx)("br",{}),"\nLabor-power is not the same as labor! Go study Marxism! -- Labor itself is a dimension? Fine! How does this dimension equal the currency dimension? (Dushulang: 2006-08-22 21:08:35)0B (0/1/1) ",(0,o.jsx)("br",{}),'\nYou yourself haven\'t learned Marx\'s theory well, you have no right to discuss "academics"! -- Are "labor" and "labor-power" the same thing? (Dushulang: 2006-08-22 21:11:52)0B (0/2/0) ',(0,o.jsx)("br",{}),'\nThe dimension of the value of the labor-power commodity is likewise the currency dimension? -- I asked you about "labor" and you bring up "labor-power"? Dodging, are we? Haha (Dushulang: 2006-08-22 21:13:15)0B (0/1/1) ',(0,o.jsx)("br",{}),'\nSeems like your "academics" are kindergarten-level too. Why do you think I asked you about two dimensions? How can the labor dimension equal the currency dimension? (Dushulang: 2006-08-22 21:22:57)0B (0/3/1)']}),"\n",(0,o.jsx)(t.p,{children:"Anyone with reading ability who reads carefully could not possibly make such replies. Can this person not understand what \"Some people who can't even grasp the concept of dimensions might ask: what is the dimension of labor? Such people fundamentally don't know what dimension means. It's like asking: 'What is the dimension of the sun?' -- anyone who asks this basically has never studied physics\" means? Can he not understand what \"From this we know that asking 'what is the dimension of the sun?' only shows that the person doesn't understand dimensions at all! Similarly, asking 'what is the dimension of labor?' is the same. But from the perspective of value measurement, the dimension of the value of the labor-power commodity is likewise the currency dimension\" means?"}),"\n",(0,o.jsx)(t.p,{children:'How could anyone possibly derive from my words that I think "\'labor\' and \'labor-power\' are the same thing"? Can he not see that the above passage is saying that "what is the dimension of labor?" is a false question, just as asking "what is the dimension of the sun?" is a false question? What is the real question? It is: "Dimension relates to measurement. For example, regarding the sun, if we examine it from the perspective of time, the dimension of the sun\'s lifespan is the dimension of time; if from the perspective of size, the dimension of the sun\'s volume is the cube of the length dimension." Similarly: "But from the perspective of value measurement, the dimension of the value of the labor-power commodity is likewise the currency dimension."'}),"\n",(0,o.jsx)(t.p,{children:'"The dimension of labor" and "the dimension of the sun" are equally pseudo-concepts. Only from the perspective of measurement do dimensions exist -- for example, lifespan, length, value, etc. The logical relationship above is so clear, why would there still be comprehension errors? If those who oppose Marx can\'t even understand one of my posts correctly, is the Marx that these anti-Marx people understand still Marx? Scholarship is not child\'s play, not a contest of tempers. First understand someone else\'s ideas properly -- this is the most basic academic requirement. Can this also be observed on forums? I hope this is not a false proposition!'})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}}}]);